@php
    $currency = config('microfinance.currency');
    $compactAmount = function (float|int|string $amount) use ($currency): string {
        $value = (float) $amount;
        return $currency.' '.($value >= 1000000000 ? number_format($value / 1000000000, 1).'B' : ($value >= 1000000 ? number_format($value / 1000000, 1).'M' : ($value >= 1000 ? number_format($value / 1000, 1).'K' : number_format($value, 0))));
    };
    $openPrincipal = (float) $openLoans->sum('outstanding_principal');
    $arrearsPrincipal = (float) $openLoans->where('days_past_due', '>', 0)->sum('outstanding_principal');
    $riskTotal = max(1, (float) $riskBuckets->sum('amount'));
    $trendMaximum = max(1, (float) $monthlyTrend->flatMap(fn ($month) => [$month['disbursed'], $month['collected']])->max());
    $filteredPrincipal = (float) $yearLoans->sum('principal_amount');
    $filteredCollections = (float) $yearRepayments->sum('amount');
    $collectionRate = $filteredPrincipal > 0 ? min(100, ($filteredCollections / $filteredPrincipal) * 100) : 0;
    $onTimeRate = $openLoans->count() > 0 ? ($dashboardStats['onSchedule'] / $openLoans->count()) * 100 : 0;
    $genderTotal = max(1, $genderDistribution->sum());
    $genderColors = ['Unknown' => '#94a3b8', 'Male' => '#2563eb', 'Female' => '#db2777', 'Other' => '#7c3aed'];
    $genderStops = [];
    $genderOffset = 0;
    foreach ($genderDistribution as $gender => $count) {
        $nextOffset = $genderOffset + ($count / $genderTotal * 100);
        $genderStops[] = ($genderColors[$gender] ?? '#0f766e').' '.$genderOffset.'% '.$nextOffset.'%';
        $genderOffset = $nextOffset;
    }
@endphp
