<script>document.querySelectorAll('[data-dashboard-tab]').forEach(function(button){button.addEventListener('click',function(){const name=button.dataset.dashboardTab;document.querySelectorAll('[data-dashboard-tab]').forEach(function(tab){tab.classList.toggle('active',tab===button)});document.querySelectorAll('[data-dashboard-panel]').forEach(function(panel){panel.hidden=panel.dataset.dashboardPanel!==name});history.replaceState(null,'','#dashboard-'+name);});});const initial=location.hash.replace('#dashboard-','');if(['overview','members','loans'].includes(initial)){document.querySelector('[data-dashboard-tab="'+initial+'"]').click();}</script>
